#include <vector>
#include <algorithm>

class Solution {
public:
    long long totalInteractionCost(int n, std::vector<std::vector<int>>& edges, std::vector<int>& groups) {
        std::vector<std::vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        int numGroups = 0;
        for (int g : groups) numGroups = std::max(numGroups, g + 1);
        std::vector<int> totalGroup(numGroups, 0);
        for (int g : groups) totalGroup[g]++;

        long long ans = 0;
        auto dfs = [&](auto self, int u, int p) -> std::vector<int> {
            std::vector<int> sub(numGroups, 0);
            sub[groups[u]]++;
            for (int v : adj[u]) {
                if (v != p) {
                    auto child = self(self, v, u);
                    for (int g = 0; g < numGroups; ++g) {
                        int c = child[g];
                        int rem = totalGroup[g] - c;
                        ans += (long long)c * rem;
                        sub[g] += c;
                    }
                }
            }
            return sub;
        };
        dfs(dfs, 0, -1);
        return ans;
    }
};

import java.util.*;

class Solution {
    private long ans = 0;

    public long totalInteractionCost(int n, int[][] edges, int[] groups) {
        ans = 0;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        int numGroups = 0;
        for (int g : groups) numGroups = Math.max(numGroups, g + 1);
        int[] totalGroup = new int[numGroups];
        for (int g : groups) totalGroup[g]++;

        dfs(0, -1, adj, groups, numGroups, totalGroup);
        return ans;
    }

    private int[] dfs(int u, int p, List<List<Integer>> adj, int[] groups, int numGroups, int[] totalGroup) {
        int[] sub = new int[numGroups];
        sub[groups[u]]++;
        for (int v : adj.get(u)) {
            if (v != p) {
                int[] child = dfs(v, u, adj, groups, numGroups, totalGroup);
                for (int g = 0; g < numGroups; g++) {
                    int c = child[g];
                    int rem = totalGroup[g] - c;
                    ans += (long)c * rem;
                    sub[g] += c;
                }
            }
        }
        return sub;
    }
}

