    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const numGroups = Math.max(...groups) + 1;
    const totalGroup = new Array(numGroups).fill(0);
    for (const g of groups) totalGroup[g]++;

    let ans = 0;
    function dfs(u, p) {
        const sub = new Array(numGroups).fill(0);
        sub[groups[u]]++;
        for (const v of adj[u]) {
            if (v !== p) {
                const child = dfs(v, u);
                for (let g = 0; g < numGroups; g++) {
                    const c = child[g];
                    const rem = totalGroup[g] - c;
                    ans += c * rem;
                    sub[g] += c;
                }
            }
        }
        return sub;
    }
    dfs(0, -1);
    return ans;
}
